-- Migration: 0103_seed_builtin_legal_pages
-- Description: Create the built-in Privacy Policy and Terms of Service pages for
-- every existing site, with a published revision each.
--
-- The default footer has linked to /privacy-policy and /terms-of-service since
-- 0072, but no migration ever created them, so both 404 on every storefront
-- (issue #72). 0073 updates these page ids without anything inserting them and
-- has been a no-op since it landed.
--
-- Generated by scripts/generate-legal-pages-migration.ts from pageDefaults.ts.
-- Do not edit by hand; re-run the script instead.
--
-- Rollback:
--   DELETE FROM page_revisions WHERE notes = 'Default configuration v3'
--     AND page_id IN (SELECT id FROM pages WHERE slug IN ('/privacy-policy', '/terms-of-service'));
--   DELETE FROM pages WHERE slug IN ('/privacy-policy', '/terms-of-service') AND is_builtin = 1;

-- Privacy Policy (/privacy-policy)
--
-- The id matches seedBuiltinPage: the bare builtin id on default-site, and
-- suffixed with the site id everywhere else, because pages.id is a global key.
-- Skipped for any site that already has a page on this slug, so a tenant who
-- already wrote their own policy keeps it.
INSERT INTO pages (id, site_id, title, slug, status, is_builtin, created_at, updated_at)
SELECT
  CASE WHEN s.id = 'default-site' THEN 'builtin-privacy-policy-page'
       ELSE 'builtin-privacy-policy-page--' || s.id END,
  s.id,
  'Privacy Policy',
  '/privacy-policy',
  'published',
  1,
  strftime('%s', 'now'),
  strftime('%s', 'now')
FROM sites s
WHERE NOT EXISTS (
  SELECT 1 FROM pages p WHERE p.site_id = s.id AND p.slug = '/privacy-policy'
);

